//! The blitters upstream generates with `sdlgenblit.pl`: one function per
//! source format, destination format and combination of modulation,
//! blending and scaling.
//!
//! Instead of generating 168 functions as source, [`blit_auto`] is the
//! generator's template: its const parameters select the same code paths
//! the script selects when it writes each function out (`$modulate`,
//! `$blend`, `$scale`, `$A_is_const_FF`, `$is_modulateA_done`, the
//! matching-color shortcuts), and the compiler instantiates it per table
//! entry. [`GENERATED_BLIT_FUNC_TABLE`] lists the entries in the script's
//! order, which matters because `SDL_ChooseBlitFunc()` takes the first match.

use super::*;

// The formats we're actually creating blitters for:
const XRGB8888: u8 = 0;
const XBGR8888: u8 = 1;
const ARGB8888: u8 = 2;
const RGBA8888: u8 = 3;
const ABGR8888: u8 = 4;
const BGRA8888: u8 = 5;

/// `$format =~ /A/`
const fn has_alpha(f: u8) -> bool {
    matches!(f, ARGB8888 | RGBA8888 | ABGR8888 | BGRA8888)
}

/// The color order once `[XA8]` is removed: 0 = "RGB", 1 = "BGR".
const fn color_order(f: u8) -> u8 {
    match f {
        XRGB8888 | ARGB8888 | RGBA8888 => 0,
        _ => 1,
    }
}

/// `substr $format, 0, 1` is "A".
const fn starts_with_a(f: u8) -> bool {
    matches!(f, ARGB8888 | ABGR8888)
}

/// `%get_rgba_string` / `%get_rgba_string_ignore_alpha`: (R, G, B, A); A is
/// 0 when not read.
#[inline(always)]
fn get_rgba(f: u8, p: u32, with_alpha: bool) -> (u32, u32, u32, u32) {
    let b8 = |v: u32| v as u8 as u32;
    let (r, g, b) = match f {
        XRGB8888 | ARGB8888 => (b8(p >> 16), b8(p >> 8), b8(p)),
        XBGR8888 | ABGR8888 => (b8(p), b8(p >> 8), b8(p >> 16)),
        RGBA8888 => (b8(p >> 24), b8(p >> 16), b8(p >> 8)),
        _ => (b8(p >> 8), b8(p >> 16), b8(p >> 24)), // BGRA8888
    };
    let a = if with_alpha && has_alpha(f) {
        match f {
            ARGB8888 | ABGR8888 => b8(p >> 24),
            _ => b8(p), // RGBA8888, BGRA8888
        }
    } else {
        0
    };
    (r, g, b, a)
}

/// `%set_rgba_string`.
#[inline(always)]
fn set_rgba(f: u8, r: u32, g: u32, b: u32, a: u32) -> u32 {
    match f {
        XRGB8888 => (r << 16) | (g << 8) | b,
        XBGR8888 => (b << 16) | (g << 8) | r,
        ARGB8888 => (a << 24) | (r << 16) | (g << 8) | b,
        RGBA8888 => (r << 24) | (g << 16) | (b << 8) | a,
        ABGR8888 => (a << 24) | (b << 16) | (g << 8) | r,
        _ => (b << 24) | (g << 16) | (r << 8) | a, // BGRA8888
    }
}

/// The settings `output_copyfunc()` derives for one function.
struct Shape {
    dst_has_alpha: bool,
    src_has_alpha: bool,
    ignore_dst_alpha: bool,
    is_modulate_a_done: bool,
    a_is_const_ff: bool,
}

const fn shape(src: u8, dst: u8, modulate: bool, blend: bool) -> Shape {
    let dst_has_alpha = has_alpha(dst);
    let src_has_alpha = has_alpha(src);
    let ignore_dst_alpha = !dst_has_alpha && !blend;
    let mut is_modulate_a_done = false;
    let mut a_is_const_ff = false;
    if blend {
        if !ignore_dst_alpha && !src_has_alpha {
            if modulate {
                is_modulate_a_done = true;
            } else {
                a_is_const_ff = true;
            }
        }
    } else if (modulate || src != dst) && !ignore_dst_alpha && !src_has_alpha {
        if modulate {
            is_modulate_a_done = true;
        } else {
            a_is_const_ff = true;
        }
    }
    Shape {
        dst_has_alpha,
        src_has_alpha,
        ignore_dst_alpha,
        is_modulate_a_done,
        a_is_const_ff,
    }
}

fn clamp255(v: u32) -> u32 {
    if v > 255 {
        255
    } else {
        v
    }
}

/// `output_copycore()`: the new destination pixel for one source pixel.
#[inline(always)]
fn copycore<const S: u8, const D: u8, const MODULATE: bool, const BLEND: bool>(
    info: &BlitInfo<'_>,
    srcpixel: u32,
    dst: &[u8],
    di: usize,
) -> u32 {
    let sh = shape(S, D, MODULATE, BLEND);
    let flags = info.flags;
    let (modulate_r, modulate_g, modulate_b, modulate_a) =
        (info.r as u32, info.g as u32, info.b as u32, info.a as u32);
    // `A`/`srcA` when the source has no alpha channel
    let const_a = if sh.is_modulate_a_done {
        if flags & COPY_MODULATE_ALPHA != 0 {
            modulate_a
        } else {
            0xFF
        }
    } else {
        0xFF
    };

    if !MODULATE && !BLEND {
        // Nice and easy...
        if S == D {
            return srcpixel;
        }

        // Matching color-order
        if color_order(S) == color_order(D) {
            let mut pixelvalue = srcpixel;
            if sh.dst_has_alpha && sh.src_has_alpha {
                if starts_with_a(D) {
                    // RGBA -> ARGB
                    pixelvalue = pixelvalue.rotate_right(8); // (pixelvalue >> 8) | (pixelvalue << 24)
                } else {
                    // ARGB -> RGBA -- unused
                    pixelvalue = (pixelvalue << 8) | const_a;
                }
            } else if sh.dst_has_alpha {
                if starts_with_a(D) {
                    // XRGB -> ARGB
                    pixelvalue |= const_a << 24;
                } else {
                    // XRGB -> RGBA -- unused
                    pixelvalue = (pixelvalue << 8) | const_a;
                }
            } else if starts_with_a(S) {
                // ARGB -> XRGB
                pixelvalue &= 0xFFFFFF;
            } else {
                // RGBA -> XRGB
                pixelvalue >>= 8;
            }
            return pixelvalue;
        }
    }

    if BLEND {
        let (mut s_r, mut s_g, mut s_b, s_a_read) = get_rgba(S, srcpixel, !sh.ignore_dst_alpha);
        let mut s_a = if sh.src_has_alpha { s_a_read } else { const_a };
        let dstpixel = rd32(dst, di);
        let (mut d_r, mut d_g, mut d_b, mut d_a) = get_rgba(D, dstpixel, sh.dst_has_alpha);

        if MODULATE {
            if flags & COPY_MODULATE_COLOR != 0 {
                s_r = mult_div_255(s_r, modulate_r);
                s_g = mult_div_255(s_g, modulate_g);
                s_b = mult_div_255(s_b, modulate_b);
            }
            if !sh.ignore_dst_alpha && !sh.is_modulate_a_done && flags & COPY_MODULATE_ALPHA != 0 {
                s_a = mult_div_255(s_a, modulate_a);
            }
        }
        if !sh.a_is_const_ff && flags & (COPY_BLEND | COPY_ADD) != 0 && s_a < 255 {
            s_r = mult_div_255(s_r, s_a);
            s_g = mult_div_255(s_g, s_a);
            s_b = mult_div_255(s_b, s_a);
        }
        match flags & COPY_BLEND_MASK {
            COPY_BLEND => {
                if sh.a_is_const_ff {
                    d_r = s_r;
                    d_g = s_g;
                    d_b = s_b;
                } else {
                    d_r = mult_div_255(255 - s_a, d_r) + s_r;
                    d_g = mult_div_255(255 - s_a, d_g) + s_g;
                    d_b = mult_div_255(255 - s_a, d_b) + s_b;
                }
                if sh.dst_has_alpha {
                    if sh.a_is_const_ff {
                        d_a = 0xFF;
                    } else {
                        d_a = mult_div_255(255 - s_a, d_a) + s_a;
                    }
                }
            }
            COPY_BLEND_PREMULTIPLIED => {
                if sh.a_is_const_ff {
                    d_r = s_r;
                    d_g = s_g;
                    d_b = s_b;
                } else {
                    d_r = clamp255(mult_div_255(255 - s_a, d_r) + s_r);
                    d_g = clamp255(mult_div_255(255 - s_a, d_g) + s_g);
                    d_b = clamp255(mult_div_255(255 - s_a, d_b) + s_b);
                }
                if sh.dst_has_alpha {
                    if sh.a_is_const_ff {
                        d_a = 0xFF;
                    } else {
                        d_a = clamp255(mult_div_255(255 - s_a, d_a) + s_a);
                    }
                }
            }
            COPY_ADD | COPY_ADD_PREMULTIPLIED => {
                d_r = clamp255(s_r + d_r);
                d_g = clamp255(s_g + d_g);
                d_b = clamp255(s_b + d_b);
            }
            COPY_MOD => {
                d_r = mult_div_255(s_r, d_r);
                d_g = mult_div_255(s_g, d_g);
                d_b = mult_div_255(s_b, d_b);
            }
            COPY_MUL => {
                if sh.a_is_const_ff {
                    d_r = mult_div_255(s_r, d_r);
                    d_g = mult_div_255(s_g, d_g);
                    d_b = mult_div_255(s_b, d_b);
                } else {
                    d_r = clamp255(mult_div_255(s_r, d_r) + mult_div_255(d_r, 255 - s_a));
                    d_g = clamp255(mult_div_255(s_g, d_g) + mult_div_255(d_g, 255 - s_a));
                    d_b = clamp255(mult_div_255(s_b, d_b) + mult_div_255(d_b, 255 - s_a));
                }
            }
            _ => {}
        }
        set_rgba(D, d_r, d_g, d_b, d_a)
    } else {
        let (mut r, mut g, mut b, a_read) = get_rgba(S, srcpixel, !sh.ignore_dst_alpha);
        let mut a = if sh.src_has_alpha { a_read } else { const_a };
        if MODULATE {
            if flags & COPY_MODULATE_COLOR != 0 {
                r = mult_div_255(r, modulate_r);
                g = mult_div_255(g, modulate_g);
                b = mult_div_255(b, modulate_b);
            }
            if !sh.ignore_dst_alpha && !sh.is_modulate_a_done && flags & COPY_MODULATE_ALPHA != 0 {
                a = mult_div_255(a, modulate_a);
            }
        }
        set_rgba(D, r, g, b, a)
    }
}

/// The template of every function in `SDL_blit_auto.c` (`output_copyfunc()`).
pub(crate) fn blit_auto<
    const S: u8,
    const D: u8,
    const MODULATE: bool,
    const BLEND: bool,
    const SCALE: bool,
>(
    info: &mut BlitInfo<'_>,
) {
    if SCALE {
        let incy = ((info.src_h as u64) << 16) / info.dst_h as u64;
        let incx = ((info.src_w as u64) << 16) / info.dst_w as u64;
        let mut posy = incy / 2;

        let mut row = 0usize;
        for _ in 0..info.dst_h {
            let mut d = row;
            let mut posx = incx / 2;

            let srcy = posy >> 16;
            for _ in 0..info.dst_w {
                let srcx = posx >> 16;
                let s = (srcy * info.src_pitch as u64 + srcx * 4) as usize;
                let v = copycore::<S, D, MODULATE, BLEND>(info, rd32(info.src, s), info.dst, d);
                wr32(info.dst, d, v);
                posx += incx;
                d += 4;
            }
            posy += incy;
            row += info.dst_pitch as usize;
        }
    } else {
        let (mut srow, mut drow) = (0usize, 0usize);
        for _ in 0..info.dst_h {
            let (mut s, mut d) = (srow, drow);
            for _ in 0..info.dst_w {
                let v = copycore::<S, D, MODULATE, BLEND>(info, rd32(info.src, s), info.dst, d);
                wr32(info.dst, d, v);
                s += 4;
                d += 4;
            }
            srow += info.src_pitch as usize;
            drow += info.dst_pitch as usize;
        }
    }
}

macro_rules! entry {
    ($s:ident, $d:ident, $m:literal, $b:literal, $sc:literal, $suffix:literal) => {
        BlitFuncEntry {
            src_format: PixelFormat::$s,
            dst_format: PixelFormat::$d,
            flags: (if $m { COPY_MODULATE_MASK } else { 0 })
                | (if $b { COPY_BLEND_MASK } else { 0 })
                | (if $sc { COPY_NEAREST } else { 0 }),
            func: NamedBlit {
                func: blit_auto::<$s, $d, $m, $b, $sc>,
                name: concat!("SDL_Blit_", stringify!($s), "_", stringify!($d), $suffix),
            },
        }
    };
}

macro_rules! generated_table {
    ($(($s:ident, $d:ident)),* $(,)?) => {
        &[$(
            entry!($s, $d, false, false, true, "_Scale"),
            entry!($s, $d, false, true, false, "_Blend"),
            entry!($s, $d, false, true, true, "_Blend_Scale"),
            entry!($s, $d, true, false, false, "_Modulate"),
            entry!($s, $d, true, false, true, "_Modulate_Scale"),
            entry!($s, $d, true, true, false, "_Modulate_Blend"),
            entry!($s, $d, true, true, true, "_Modulate_Blend_Scale"),
        )*]
    };
}

/// Translation of `SDL_GeneratedBlitFuncTable` (without the terminating
/// `{ SDL_PIXELFORMAT_UNKNOWN, ... NULL }` entry).
pub(crate) static GENERATED_BLIT_FUNC_TABLE: &[BlitFuncEntry] = generated_table![
    (XRGB8888, XRGB8888),
    (XRGB8888, XBGR8888),
    (XRGB8888, ARGB8888),
    (XRGB8888, ABGR8888),
    (XBGR8888, XRGB8888),
    (XBGR8888, XBGR8888),
    (XBGR8888, ARGB8888),
    (XBGR8888, ABGR8888),
    (ARGB8888, XRGB8888),
    (ARGB8888, XBGR8888),
    (ARGB8888, ARGB8888),
    (ARGB8888, ABGR8888),
    (RGBA8888, XRGB8888),
    (RGBA8888, XBGR8888),
    (RGBA8888, ARGB8888),
    (RGBA8888, ABGR8888),
    (ABGR8888, XRGB8888),
    (ABGR8888, XBGR8888),
    (ABGR8888, ARGB8888),
    (ABGR8888, ABGR8888),
    (BGRA8888, XRGB8888),
    (BGRA8888, XBGR8888),
    (BGRA8888, ARGB8888),
    (BGRA8888, ABGR8888),
];
